166→   166→---
167→   167→
168→   168→### Task 2: 사이드바 컴포넌트 생성
169→   169→
170→   170→**Files:**
171→   171→- Create: `components/sidebar.tsx`
172→   172→
173→   173→- [ ] **Step 1: 사이드바 컴포넌트 작성**
174→   174→
175→   175→역할 기반 하드코딩 메뉴 (3단계에서 permissions 기반으로 전환 예정):
176→   176→
177→   177→```tsx
178→   178→"use client";
179→   179→
180→   180→import { usePathname } from "next/navigation";
181→   181→import Link from "next/link";
182→   182→import Image from "next/image";
183→   183→import type { AuthUser } from "@/lib/types";
184→   184→
185→   185→type MenuItem = {
186→   186→  label: string;
187→   187→  href: string;
188→   188→  icon: string;
189→   189→};
190→   190→
191→   191→type MenuSection = {
192→   192→  title?: string;
193→   193→  items: MenuItem[];
194→   194→};
195→   195→
196→   196→const ADMIN_MENU: MenuSection[] = [
197→   197→  {
198→   198→    items: [
199→   199→      { label: "현황 요약", href: "/summary", icon: "📊" },
200→   200→      { label: "TO 배분표", href: "/allocation", icon: "📋" },
201→   201→      { label: "채용 진행현황", href: "/progress", icon: "🔄" },
202→   202→      { label: "후보자 관리", href: "/candidates", icon: "👤" },
203→   203→    ],
204→   204→  },
205→   205→  {
206→   206→    title: "관리",
207→   207→    items: [
208→   208→      { label: "데이터 관리", href: "/data-sheet", icon: "⚙️" },
209→   209→      { label: "워크플로우", href: "/workflow", icon: "📐" },
210→   210→    ],
211→   211→  },
212→   212→  {
213→   213→    title: "시스템",
214→   214→    items: [
215→   215→      { label: "권한 관리", href: "/permissions", icon: "🔐" },
216→   216→      { label: "사용자 관리", href: "/users", icon: "👥" },
217→   217→    ],
218→   218→  },
219→   219→];
220→   220→
221→   221→const DEAN_MENU: MenuSection[] = [
222→   222→  {
223→   223→    items: [
224→   224→      { label: "학과 현황", href: "/summary", icon: "📊" },
225→   225→      { label: "채용 진행현황", href: "/progress", icon: "🔄" },
226→   226→      { label: "후보자 관리", href: "/candidates", icon: "👤" },
227→   227→      { label: "채용 요청", href: "/candidates", icon: "📝" },
228→   228→      { label: "단계별 제출", href: "/progress", icon: "✅" },
229→   229→    ],
230→   230→  },
231→   231→];
232→   232→
233→   233→function getMenuForRole(role: string): MenuSection[] {
234→   234→  if (role === "DEAN") return DEAN_MENU;
235→   235→  return ADMIN_MENU; // ADMIN, VIP 모두 전체 메뉴
236→   236→}
237→   237→
238→   238→export default function Sidebar({ user }: { user: AuthUser }) {
239→   239→  const pathname = usePathname();
240→   240→  const menu = getMenuForRole(user.role);
241→   241→
242→   242→  return (
243→   243→    <aside
244→   244→      style={{
245→   245→        width: 220,
246→   246→        background: "var(--sidebar-bg)",
247→   247→        padding: "20px 0",
248→   248→        flexShrink: 0,
249→   249→        position: "fixed",
250→   250→        top: 0,
251→   251→        left: 0,
252→   252→        bottom: 0,
253→   253→        display: "flex",
254→   254→        flexDirection: "column",
255→   255→        zIndex: 50,
256→   256→      }}
257→   257→    >
258→   258→      {/* Logo */}
259→   259→      <div style={{ padding: "0 20px 20px" }}>
260→   260→        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
261→   261→          <Image
262→   262→            src="/logo_SKKU_transparent.png"
263→   263→            alt="SKKU"
264→   264→            width={28}
265→   265→            height={28}
266→   266→            style={{ objectFit: "contain" }}
267→   267→          />
268→   268→          <div>
269→   269→            <div style={{ fontWeight: 600, fontSize: 13, color: "var(--sidebar-text-active)" }}>
270→   270→              교원채용
271→   271→            </div>
272→   272→            <div style={{ fontSize: 10, color: "var(--sidebar-section)" }}>
273→   273→              성균관대학교
274→   274→            </div>
275→   275→          </div>
276→   276→        </div>
277→   277→      </div>
278→   278→
279→   279→      {/* Menu */}
280→   280→      <nav style={{ flex: 1, padding: "8px 10px 0", overflowY: "auto" }}>
281→   281→        {menu.map((section, si) => (
282→   282→          <div key={si}>
283→   283→            {section.title && (
284→   284→              <div
285→   285→                style={{
286→   286→                  margin: "14px 14px 6px",
287→   287→                  fontSize: 10,
288→   288→                  color: "var(--sidebar-section)",
289→   289→                  textTransform: "uppercase",
290→   290→                  fontWeight: 600,
291→   291→                  letterSpacing: 0.5,
292→   292→                }}
293→   293→              >
294→   294→                {section.title}
295→   295→              </div>
296→   296→            )}
297→   297→            {section.items.map((item) => {
298→   298→              const isActive = pathname === item.href;
299→   299→              return (
300→   300→                <Link
301→   301→                  key={item.href + item.label}
302→   302→                  href={item.href}
303→   303→                  style={{
304→   304→                    display: "block",
305→   305→                    padding: "9px 14px",
306→   306→                    borderRadius: 8,
307→   307→                    fontSize: 13,
308→   308→                    fontWeight: isActive ? 500 : 400,
309→   309→                    color: isActive ? "var(--sidebar-text-active)" : "var(--sidebar-text)",
310→   310→                    background: isActive ? "var(--sidebar-hover)" : "transparent",
311→   311→                    textDecoration: "none",
312→   312→                    marginBottom: 2,
313→   313→                  }}
314→   314→                >
315→   315→                  {item.icon} {item.label}
316→   316→                </Link>
317→   317→              );
318→   318→            })}
319→   319→          </div>
320→   320→        ))}
321→   321→      </nav>
322→   322→
323→   323→      {/* User info */}
324→   324→      <div
325→   325→        style={{
326→   326→          padding: "14px 20px",
327→   327→          borderTop: "1px solid rgba(255,255,255,0.08)",
328→   328→        }}
329→   329→      >
330→   330→        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
331→   331→          <div
332→   332→            style={{
333→   333→              width: 26,
334→   334→              height: 26,
335→   335→              background: "var(--primary-green)",
336→   336→              borderRadius: "50%",
337→   337→              display: "flex",
338→   338→              alignItems: "center",
339→   339→              justifyContent: "center",
340→   340→              color: "white",
341→   341→              fontSize: 10,
342→   342→            }}
343→   343→          >
344→   344→            {user.username.charAt(0)}
345→   345→          </div>
346→   346→          <div>
347→   347→            <div style={{ fontSize: 12, color: "#ddd" }}>{user.username}</div>
348→   348→            <div style={{ fontSize: 10, color: "var(--sidebar-section)" }}>{user.role}</div>
349→   349→          </div>
350→   350→        </div>
351→   351→      </div>
352→   352→    </aside>
353→   353→  );
354→   354→}
355→   355→```
356→   356→
357→   357→- [ ] **Step 2: 커밋**
358→   358→
359→   359→```bash
360→   360→git add components/sidebar.tsx
361→   361→git commit -m "feat: add sidebar component with role-based menu
362→   362→
363→   363→Deep green sidebar with SKKU logo, role-specific navigation menu
364→   364→(ADMIN/VIP: full menu, DEAN: department-scoped menu), and user info."
365→   365→```
366→   366→
367→   367→---
368→   368→
369→   369→### Task 3: 공통 레이아웃 전환 (layout.tsx)
370→   370→
371→   371→**Files:**
372→   372→- Modify: `app/layout.tsx`
373→   373→- Create: `app/(auth)/login/page.tsx`
374→   374→- Create: `app/(auth)/layout.tsx`
375→   375→- Delete: `app/login/page.tsx` (이동 후)
376→   376→
377→   377→- [ ] **Step 1: (auth) 그룹 레이아웃 생성**
378→   378→
379→   379→로그인 페이지는 사이드바 없이 전체 화면으로 렌더링한다:
380→   380→
381→   381→```tsx
382→   382→// app/(auth)/layout.tsx
383→   383→export default function AuthLayout({
384→   384→  children,
385→   385→}: {
386→   386→  children: React.ReactNode;
387→   387→}) {
388→   388→  return <>{children}</>;
389→   389→}
390→   390→```
391→   391→
392→   392→- [ ] **Step 2: 기존 로그인 페이지를 (auth) 그룹으로 이동**
393→   393→
394→   394→```bash
395→   395→mkdir -p app/\(auth\)/login
396→   396→cp app/login/page.tsx app/\(auth\)/login/page.tsx
397→   397→```
398→   398→
399→   399→기존 `app/login/page.tsx`를 삭제한다. 로그인 컴포넌트 `components/login-form.tsx`는 그대로 사용.
400→   400→
401→   401→- [ ] **Step 3: layout.tsx에 사이드바 통합**
402→   402→
403→   403→`app/layout.tsx`를 수정한다. 로그인 페이지는 `(auth)` route group을 사용하므로 이 레이아웃의 영향을 받지 않는다. 단, Next.js App Router에서 root layout은 모든 페이지에 적용되므로, 사이드바 표시 여부를 서버에서 판단한다:
404→   404→
405→   405→```tsx
406→   406→// app/layout.tsx
407→   407→import type { Metadata } from "next";
408→   408→import "./globals.css";
409→   409→import { getCurrentUser } from "@/lib/auth";
410→   410→import Sidebar from "@/components/sidebar";
411→   411→
412→   412→export const metadata: Metadata = {
413→   413→  title: "SKKU 교원채용 All-In-One",
414→   414→  description: "성균관대학교 교원채용 정시/상시 통합 관리자 및 보고 페이지",
415→   415→};
416→   416→
417→   417→export default async function RootLayout({
418→   418→  children,
419→   419→}: Readonly<{
420→   420→  children: React.ReactNode;
421→   421→}>) {
422→   422→  const user = await getCurrentUser();
423→   423→
424→   424→  return (
425→   425→    <html lang="ko">
426→   426→      <body>
427→   427→        {user ? (
428→   428→          <div style={{ display: "flex", minHeight: "100vh" }}>
429→   429→            <Sidebar user={user} />
430→   430→            <main
431→   431→              style={{
432→   432→                flex: 1,
433→   433→                marginLeft: 220,
434→   434→                padding: "24px 28px",
435→   435→                minHeight: "100vh",
436→   436→                background: "var(--page-bg)",
437→   437→              }}
438→   438→            >
439→   439→              {children}
440→   440→            </main>
441→   441→          </div>
442→   442→        ) : (
443→   443→          children
444→   444→        )}
445→   445→      </body>
446→   446→    </html>
447→   447→  );
448→   448→}
449→   449→```
450→   450→
451→   451→- [ ] **Step 4: 기존 페이지의 중복 레이아웃 요소 정리**
452→   452→
453→   453→`app/page.tsx` (메인 대시보드)에서 페이지 전체를 감싸던 외곽 래퍼 스타일이 있다면 제거한다. 이제 `<main>` 영역이 layout.tsx에서 제공되므로 각 페이지는 콘텐츠만 렌더링하면 된다.
454→   454→
455→   455→- [ ] **Step 5: 개발 서버에서 확인**
