685→   685→```typescript
686→   686→// lib/permissions.ts
687→   687→import { getDb } from "./db";
688→   688→
689→   689→export function checkPermission(
690→   690→  role: string,
691→   691→  resource: string,
692→   692→  action: string
693→   693→): boolean {
694→   694→  const db = getDb();
695→   695→
696→   696→  // 먼저 와일드카드 '*' 체크
697→   697→  const wildcard = db
698→   698→    .prepare(
699→   699→      "SELECT allowed FROM permissions WHERE role = ? AND resource = '*' AND action = ? LIMIT 1"
700→   700→    )
701→   701→    .get(role, action) as { allowed: number } | undefined;
702→   702→
703→   703→  if (wildcard) return wildcard.allowed === 1;
704→   704→
705→   705→  // 정확한 resource 체크
706→   706→  const exact = db
707→   707→    .prepare(
708→   708→      "SELECT allowed FROM permissions WHERE role = ? AND resource = ? AND action = ? LIMIT 1"
709→   709→    )
710→   710→    .get(role, resource, action) as { allowed: number } | undefined;
711→   711→
712→   712→  if (exact) return exact.allowed === 1;
713→   713→
714→   714→  // 권한 레코드가 없으면 거부
715→   715→  return false;
716→   716→}
717→   717→
718→   718→export function getPermissionsForRole(role: string): {
719→   719→  resource: string;
720→   720→  action: string;
721→   721→  allowed: boolean;
722→   722→}[] {
723→   723→  const db = getDb();
724→   724→  const rows = db
725→   725→    .prepare("SELECT resource, action, allowed FROM permissions WHERE role = ?")
726→   726→    .all(role) as { resource: string; action: string; allowed: number }[];
727→   727→  return rows.map((r) => ({
728→   728→    resource: r.resource,
729→   729→    action: r.action,
730→   730→    allowed: r.allowed === 1,
731→   731→  }));
732→   732→}
733→   733→
734→   734→export function updatePermissions(
735→   735→  role: string,
736→   736→  changes: { resource: string; action: string; allowed: boolean }[]
737→   737→): void {
738→   738→  const db = getDb();
739→   739→  const upsert = db.prepare(`
740→   740→    INSERT INTO permissions (role, resource, action, allowed)
741→   741→    VALUES (?, ?, ?, ?)
742→   742→    ON CONFLICT(role, resource, action)
743→   743→    DO UPDATE SET allowed = excluded.allowed, updated_at = CURRENT_TIMESTAMP
744→   744→  `);
745→   745→  const tx = db.transaction(() => {
746→   746→    for (const c of changes) {
747→   747→      upsert.run(role, c.resource, c.action, c.allowed ? 1 : 0);
748→   748→    }
749→   749→  });
750→   750→  tx();
751→   751→}
752→   752→
753→   753→export function getAllRoles(): string[] {
754→   754→  const db = getDb();
755→   755→  const rows = db
756→   756→    .prepare("SELECT DISTINCT role FROM permissions ORDER BY role")
757→   757→    .all() as { role: string }[];
758→   758→  return rows.map((r) => r.role);
759→   759→}
760→   760→
761→   761→export function createRole(role: string): void {
762→   762→  const db = getDb();
763→   763→  const RESOURCES = [
764→   764→    "dashboard.summary", "dashboard.allocation", "dashboard.progress",
765→   765→    "candidates", "procedures", "actions",
766→   766→    "admin.data-sheet", "admin.workflow",
767→   767→    "system.permissions", "system.users",
768→   768→  ];
769→   769→  const ACTIONS = ["view", "edit", "delete", "export", "import"];
770→   770→  const insert = db.prepare(
771→   771→    "INSERT OR IGNORE INTO permissions (role, resource, action, allowed) VALUES (?, ?, ?, 0)"
772→   772→  );
773→   773→  const tx = db.transaction(() => {
774→   774→    for (const resource of RESOURCES) {
