1054→  1054→    const wildcard = perms.find((p) => p.resource === "*" && p.action === action);
1055→  1055→    if (wildcard) return wildcard.allowed;
1056→  1056→    const entry = perms.find((p) => p.resource === resource && p.action === action);
1057→  1057→    return entry?.allowed ?? false;
1058→  1058→  }
